import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type DossierProfileProps = Record<string, any>;

const DossierProfile: React.FC<DossierProfileProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 8,
  accentColor = "#3b82f6",
  textColor = "#ffffff",
  labelColor = "#8b949e",
  lineColor = "#30363d",
  profileName = "Malloy Studio",
  profileTitle = "Director of Operations",
  profileImage = "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?q=80&w=800&auto=format&fit=crop",
  entries = [
    { label: "Status", value: "Active" },
    { label: "Location", value: "Classified" },
    { label: "Specialty", value: "Strategic Ops" },
    { label: "Clearance", value: "Level 5" },
    { label: "ID Number", value: "MX-89241" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Responsive unit based on the shortest side
  const u = Math.min(width, height);
  const margin = width * 0.05;
  const contentPadding = u * 0.08;

  // Global Animations
  const cornerFrame = Math.max(0, frame - 5);
  const cornerScale = spring({ fps, frame: cornerFrame, config: { damping: 15 } });
  const cornerOpacity = interpolate(cornerFrame, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Left Panel Animations
  const picScale = spring({ fps, frame, config: { damping: 14 } });
  const picOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  
  const nameY = interpolate(frame, [10, 30], [50, 0], { extrapolateRight: "clamp" });
  const nameOpacity = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" });
  
  const titleY = interpolate(frame, [15, 35], [50, 0], { extrapolateRight: "clamp" });
  const titleOpacity = interpolate(frame, [15, 35], [0, 1], { extrapolateRight: "clamp" });

  const cornerSize = u * 0.06;
  const cornerStyle = {
    position: "absolute" as const,
    width: cornerSize,
    height: cornerSize,
    opacity: cornerOpacity,
    transform: `scale(${cornerScale})`,
    transition: "none",
  };

  const picSize = u * 0.45;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Dossier Corner Accents */}
      <div style={{ ...cornerStyle, top: margin, left: margin, borderTop: `4px solid ${accentColor}`, borderLeft: `4px solid ${accentColor}` }} />
      <div style={{ ...cornerStyle, top: margin, right: margin, borderTop: `4px solid ${accentColor}`, borderRight: `4px solid ${accentColor}` }} />
      <div style={{ ...cornerStyle, bottom: margin, left: margin, borderBottom: `4px solid ${accentColor}`, borderLeft: `4px solid ${accentColor}` }} />
      <div style={{ ...cornerStyle, bottom: margin, right: margin, borderBottom: `4px solid ${accentColor}`, borderRight: `4px solid ${accentColor}` }} />

      {/* Main Content Layout */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          width: "100%",
          height: "100%",
          padding: contentPadding,
          boxSizing: "border-box",
        }}
      >
        {/* Left Column: Profile Picture & Identity */}
        <div
          style={{
            flex: 1,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            borderRight: `2px dashed ${lineColor}`,
            paddingRight: contentPadding,
          }}
        >
          <div
            style={{
              width: picSize,
              height: picSize,
              opacity: picOpacity,
              transform: `scale(${picScale})`,
              transition: "none",
              borderRadius: picSize * 0.05,
              overflow: "hidden",
              border: `4px solid ${lineColor}`,
              boxShadow: `0 0 40px ${backgroundColor}80`,
              position: "relative",
            }}
          >
            <Img
              src={profileImage}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
              }}
            />
            {/* Crosshair Overlay Overlay */}
            <div style={{ position: 'absolute', top: 0, left: '50%', width: 2, height: 20, backgroundColor: accentColor }} />
            <div style={{ position: 'absolute', bottom: 0, left: '50%', width: 2, height: 20, backgroundColor: accentColor }} />
            <div style={{ position: 'absolute', left: 0, top: '50%', width: 20, height: 2, backgroundColor: accentColor }} />
            <div style={{ position: 'absolute', right: 0, top: '50%', width: 20, height: 2, backgroundColor: accentColor }} />
          </div>

          <div
            style={{
              marginTop: u * 0.06,
              opacity: nameOpacity,
              transform: `translateY(${nameY}px)`,
              transition: "none",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
            }}
          >
            <div
              style={{
                fontFamily: interFamily,
                fontSize: u * 0.06,
                fontWeight: 800,
                color: textColor,
                textAlign: "center",
                lineHeight: 1.1,
              }}
            >
              {profileName}
            </div>
          </div>

          <div
            style={{
              marginTop: u * 0.015,
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              transition: "none",
              fontFamily: robotoMonoFamily,
              fontSize: u * 0.025,
              color: labelColor,
              textAlign: "center",
              textTransform: "uppercase",
              letterSpacing: 2,
            }}
          >
            {profileTitle}
          </div>
        </div>

        {/* Right Column: Dossier Entries */}
        <div
          style={{
            flex: 1.4,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            paddingLeft: contentPadding,
            gap: u * 0.03,
          }}
        >
          {entries.map((entry, index) => {
            const entryDelay = 25 + index * 6;
            const entryFrame = Math.max(0, frame - entryDelay);
            const entryOpacity = interpolate(entryFrame, [0, 20], [0, 1], {
              extrapolateRight: "clamp",
            });
            const entryX = interpolate(entryFrame, [0, 20], [width * 0.05, 0], {
              extrapolateRight: "clamp",
            });

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "center",
                  paddingBottom: u * 0.025,
                  borderBottom: `2px solid ${lineColor}`,
                  opacity: entryOpacity,
                  transform: `translateX(${entryX}px)`,
                  transition: "none",
                }}
              >
                <div
                  style={{
                    width: u * 0.012,
                    height: u * 0.012,
                    backgroundColor: accentColor,
                    marginRight: u * 0.025,
                    transform: "rotate(45deg)",
                  }}
                />
                <div
                  style={{
                    flex: 1,
                    fontFamily: interFamily,
                    fontSize: u * 0.025,
                    color: labelColor,
                    textTransform: "uppercase",
                    letterSpacing: 2,
                    fontWeight: 600,
                  }}
                >
                  {entry.label}
                </div>
                <div
                  style={{
                    flex: 1.5,
                    fontFamily: robotoMonoFamily,
                    fontSize: u * 0.035,
                    color: textColor,
                    fontWeight: "bold",
                  }}
                >
                  {entry.value}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DossierProfile;